SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e1020000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 102, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "102", "printedPageNumber": 102, "pdfPageNumber": 485, "sequenceIndex": 92, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f1020000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 102"}, {"id": "f1020100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said about Ali (Radhiyallaho anho) that whenever an arrow got stuck into his body (in a battle), this was drawn out during his salaat. Once he got an arrow stuck into his thigh. This could not be extracted, in spite of several efforts, due to severe pain felt by him. When he was busy in his nafl salaat and prostrate in sajdah, the people drew out the arrow with force. When he finished his salaat, he asked the people who had collected around him, \"Have you gathered to take out the arrow?\" When they told him that it was already taken out, he informed them that he had no feeling of pain during the extraction.\n\nMuslim bin Yasaar (Rahmatullah alaih), when he stood up for salaat, said to his family members, \"You may keep on talking; I shall not be aware of what you talk.\"\n\nIt is said of Aamir bin Abdullah (Rahmatullah alaih) that he would not even hear the beating of a drum while in salaat, nor to speak of the talk of people around him. A person asked him, \"Are you conscious of anything while in salaat?\" He replied, \"Yes, I am conscious of the fact that I have to stand one day before Allah, whence I shall either be sent to Paradise or Hell.\" The person said, \"No, I do not mean that. Do you come to know of anything we talk around you?\" He replied, \"It is better that spears pass through my body rather than I grow conscious of your conversation while I am in salaat.\" He used to say, \"My conviction in the things of the Hereafter is so perfect that it is impossible for it to improve, even if I happen to see those things with my physical eyes.\"\n\nA pious man was asked, \"Do you ever think of this world while you are in salaat?\" He replied, \"I never think of this world, either in salaat or out of it.\" Another such man was asked, \"Do you think of anything while in salaat?\" He replied, \"Is there anything more attractive than salaat itself to think of?\"\n\nIn ''Bahjatun Nufoos'' it is written about a Shaikh that he had either been offering fardh or nafl salaat or been absorbed in Zikr without break, right from Zuhr to Fajr of the next day. After Fajr, while continuing Zikr, he was overpowered by slumber, when immediately he recited Istighfaar and the following prayer:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 102"}, {"id": "f1020200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أَعُوذُ بِاللَّهِ مِنْ عَيْنٍ لَا تَشْبَعُ مِنَ النَّوْمِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 102"}, {"id": "f1020300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"I seek refuge in Allah from the eye that does not get satiated with sleep.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 102"}]}'::jsonb);